import (
	"fmt"
)

resp, err := client.Dashboards().ListDashboards(ctx, nil)
if err != nil {
	log.Fatal(err)
}
for _, row := range resp.Map().(map[string]any)["dashboards"].([]any) {
	dashboard := row.(map[string]any)
	fmt.Println(dashboard["id"], dashboard["name"], dashboard["default"])
}

