import (
	"fmt"
)

resp, err := client.Dashboards().PatchDashboard(ctx, "3f2b8c1e-7a4d-4e29-9b1a-5c6d7e8f9a01", map[string]any{
	"standard_sections": []any{
		map[string]any{"key": "announcement", "visible": false},
	},
}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["standard_sections"].([]any) {
	section := row.(map[string]any)
	fmt.Println(section["key"], section["visible"])
}

